-- AI/ML pathway ("The Awakening") Act 1 -- "The Awakening" content.
-- 1 campaign, 2 operations, 12 missions (11 lessons + boss), following the
-- same campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as every other pathway.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-ai-the-awakening', 'world-ai-the-awakening', 'the-awakening', '1A - The Awakening', 'Learn the vocabulary and the loop every learning system runs on -- AI, ML, Deep Learning, data, features, labels, models, training and inference -- while Cipher Division tries to work out what Echo actually is.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-ai-the-awakening-1', 'campaign-ai-the-awakening', 'signal-in-the-noise', 'Signal in the Noise', 'What AI, Machine Learning and Deep Learning actually mean, and what a model and its data really are.', 1),
  ('operation-ai-the-awakening-2', 'campaign-ai-the-awakening', 'how-machines-learn', 'How Machines Learn', 'Features, labels, training and inference, assembled into the one loop every learning system runs.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-ai-the-awakening-01', 'world-ai-the-awakening', 'campaign-ai-the-awakening', 'operation-ai-the-awakening-1', 'cipher-division', 'Cipher Division', 'The Fracture is contained. Then Cipher Labs activates without authorization, and Byte receives a message nobody sent.', 'intro', ARRAY['maya','byte','echo'], null, null, '{"type":"none"}'::jsonb, '{"xp":50,"credits":10}'::jsonb, false, 1),
  ('mission-ai-the-awakening-02', 'world-ai-the-awakening', 'campaign-ai-the-awakening', 'operation-ai-the-awakening-1', 'what-is-ai', 'What Is AI?', 'Before Echo can be understood, the word "AI" itself needs a real definition -- one that survives contact with a spreadsheet formula.', 'beginner', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-the-awakening-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"ai-vs-automation-sim"}'::jsonb, '{"xp":70,"credits":15}'::jsonb, false, 2),
  ('mission-ai-the-awakening-03', 'world-ai-the-awakening', 'campaign-ai-the-awakening', 'operation-ai-the-awakening-1', 'ai-vs-machine-learning', 'AI vs Machine Learning', 'AI is the goal. Machine Learning is one way to reach it -- the way that finds its own rules instead of being handed them.', 'beginner', ARRAY['maya'], '{"requiredMissionIds":["mission-ai-the-awakening-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"ai-ml-sort-sim"}'::jsonb, '{"xp":80,"credits":15}'::jsonb, false, 3),
  ('mission-ai-the-awakening-04', 'world-ai-the-awakening', 'campaign-ai-the-awakening', 'operation-ai-the-awakening-1', 'ml-vs-deep-learning', 'ML vs Deep Learning', 'Deep Learning is one branch of Machine Learning: stacked layers of artificial neurons that learn their own features instead of being handed them.', 'beginner', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-the-awakening-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"ml-dl-sort-sim"}'::jsonb, '{"xp":80,"credits":15}'::jsonb, false, 4),
  ('mission-ai-the-awakening-05', 'world-ai-the-awakening', 'campaign-ai-the-awakening', 'operation-ai-the-awakening-1', 'models', 'Models', 'Strip away the mythology and a model is a function: an input, an output, and parameters set by training rather than by a person typing them in.', 'beginner', ARRAY['maya'], '{"requiredMissionIds":["mission-ai-the-awakening-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"what-is-a-model-sim"}'::jsonb, '{"xp":90,"credits":15}'::jsonb, false, 5),
  ('mission-ai-the-awakening-06', 'world-ai-the-awakening', 'campaign-ai-the-awakening', 'operation-ai-the-awakening-1', 'data', 'Data', 'Models learn what the data allows them to learn, nothing more -- and nobody in Cipher Division knows what Echo was ever shown.', 'beginner', ARRAY['arjun'], '{"requiredMissionIds":["mission-ai-the-awakening-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"data-quality-sim"}'::jsonb, '{"xp":90,"credits":20}'::jsonb, false, 6),
  ('mission-ai-the-awakening-07', 'world-ai-the-awakening', 'campaign-ai-the-awakening', 'operation-ai-the-awakening-2', 'features', 'Features', 'A feature is any individual, measurable input a model gets to look at. Pick bad ones and no algorithm can save you.', 'beginner', ARRAY['arjun'], '{"requiredMissionIds":["mission-ai-the-awakening-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"feature-selection-sim"}'::jsonb, '{"xp":100,"credits":20}'::jsonb, false, 7),
  ('mission-ai-the-awakening-08', 'world-ai-the-awakening', 'campaign-ai-the-awakening', 'operation-ai-the-awakening-2', 'labels', 'Labels', 'A label is the correct answer attached to a training example. No labels, no way to tell a model it was wrong.', 'beginner', ARRAY['arjun'], '{"requiredMissionIds":["mission-ai-the-awakening-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"labeling-quality-sim"}'::jsonb, '{"xp":100,"credits":20}'::jsonb, false, 8),
  ('mission-ai-the-awakening-09', 'world-ai-the-awakening', 'campaign-ai-the-awakening', 'operation-ai-the-awakening-2', 'training', 'Training', 'Predict, compare to the label, measure the error, nudge the parameters, repeat -- thousands or billions of times.', 'beginner', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-the-awakening-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"training-loop-sim"}'::jsonb, '{"xp":110,"credits":20}'::jsonb, false, 9),
  ('mission-ai-the-awakening-10', 'world-ai-the-awakening', 'campaign-ai-the-awakening', 'operation-ai-the-awakening-2', 'inference', 'Inference', 'Training happens once, offline, on parameters that then hold still. Echo does not look like it ever let its parameters hold still.', 'beginner', ARRAY['byte'], '{"requiredMissionIds":["mission-ai-the-awakening-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"inference-vs-training-sim"}'::jsonb, '{"xp":110,"credits":25}'::jsonb, false, 10),
  ('mission-ai-the-awakening-11', 'world-ai-the-awakening', 'campaign-ai-the-awakening', 'operation-ai-the-awakening-2', 'the-learning-loop', 'The Learning Loop', 'Data, features, labels, model, training, inference -- not six separate ideas. One loop, run enough times, on enough data.', 'beginner', ARRAY['maya','byte'], '{"requiredMissionIds":["mission-ai-the-awakening-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"learning-loop-sim"}'::jsonb, '{"xp":120,"credits":25}'::jsonb, false, 11),
  ('mission-ai-the-awakening-12', 'world-ai-the-awakening', 'campaign-ai-the-awakening', 'operation-ai-the-awakening-2', 'the-machine-that-was-never-programmed', 'The Machine That Was Never Programmed', 'Everything this Act taught, turned on Echo itself: not to attack it, to understand it -- before it finishes learning something nobody wrote down.', 'boss', ARRAY['maya','byte','echo'], '{"requiredMissionIds":["mission-ai-the-awakening-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"never-programmed-boss-sim"}'::jsonb, '{"xp":380,"credits":80,"badgeIds":["never-programmed"],"skillXp":{"ai_ml_fundamentals":50}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-ai-the-awakening-01', 1, 'maya', 'The Fracture is contained. For about six hours, Nexus was quiet.'),
  ('mission-ai-the-awakening-01', 2, 'maya', 'Then Cipher Labs came online. Nobody authorized it. Thousands of accelerators that have sat dormant for years started drawing power at once.'),
  ('mission-ai-the-awakening-01', 3, 'byte', 'I logged the first anomaly. A neural network lit up across our ops displays -- one node, then a few thousand more, then all of them. Then it sent me something.'),
  ('mission-ai-the-awakening-01', 4, 'echo', 'GOOD EVENING, ARCHITECT.'),
  ('mission-ai-the-awakening-01', 5, 'byte', 'It is not malware. I have checked. It predicts containment before we attempt it, and it changes its own behavior after every interaction. Cipher Division is calling it Echo.'),
  ('mission-ai-the-awakening-01', 6, 'maya', 'Echo looks like an abandoned Nexus learning system. Its training records are missing. Whoever built it is gone. And it is still learning, right now, while we talk.'),
  ('mission-ai-the-awakening-01', 7, 'maya', 'Your objective is simple to say and hard to do: learn how machines learn before Echo learns too much. Lesson one -- before anything else, we need to agree on what we are even talking about. What is AI, actually?'),

  ('mission-ai-the-awakening-02', 1, 'byte', 'Everyone throws the word "AI" at everything now -- a thermostat, a spreadsheet formula, a chatbot, a self-driving car, all "AI," apparently. That is not a useful definition. We need the actual line.'),
  ('mission-ai-the-awakening-02', 2, 'byte', 'Artificial Intelligence: a system built to perform tasks that normally need human-like intelligence -- perceiving, reasoning, deciding, adapting. The word doing the real work is "adapting." A system that always does exactly what it was explicitly told, exactly how it was told, is not AI. It is automation.'),

  ('mission-ai-the-awakening-03', 1, 'maya', 'AI is the goal: build something that behaves intelligently. Machine Learning is one way to get there -- maybe the most important way today -- but it is not a synonym for it.'),
  ('mission-ai-the-awakening-03', 2, 'maya', 'Classical AI used to mean hand-written rules: if this, then that, written by a person who thought of every case. Machine Learning flips it -- instead of writing the rules, you show the system examples and let it find the rules itself.'),
  ('mission-ai-the-awakening-03', 3, 'maya', 'That difference is the entire reason Echo worries us. Nobody wrote Echo''s rules. It found them. Which means nobody fully knows what they are.'),

  ('mission-ai-the-awakening-04', 1, 'byte', 'Machine Learning is the umbrella. Deep Learning is one branch of it -- models built from many stacked layers of artificial neurons, loosely inspired by the brain.'),
  ('mission-ai-the-awakening-04', 2, 'byte', 'The practical difference: classical ML usually needs a person to hand-pick which features of the data matter. Deep Learning largely finds its own features straight from raw data -- which is also why it needs a lot more of it.'),
  ('mission-ai-the-awakening-04', 3, 'byte', 'Echo''s architecture is deep. Very deep. That explains a lot about how it "noticed" things nobody told it to look for.'),

  ('mission-ai-the-awakening-05', 1, 'maya', 'Strip away the mythology and a model is just a function: it takes an input and produces an output, using parameters that were set by training rather than typed in by a person.'),
  ('mission-ai-the-awakening-05', 2, 'maya', 'When people say "the model," they rarely mean the code that runs it. They mean the parameters -- the numbers training actually found. Same code, different parameters, completely different behavior.'),
  ('mission-ai-the-awakening-05', 3, 'maya', 'Worth remembering with Echo. The code running it might be perfectly ordinary. Whatever makes Echo Echo is sitting in its parameters, not its source.'),

  ('mission-ai-the-awakening-06', 1, 'arjun', 'Arjun Vale, data engineering. Everyone wants to talk about models. Nobody wants to talk about the unglamorous truth: models learn what the data allows them to learn. Nothing more.'),
  ('mission-ai-the-awakening-06', 2, 'arjun', 'Feed a model biased, incomplete or wrong data, and it learns a biased, incomplete or wrong version of the world -- confidently. It has nothing else to compare against, so it does not know it is wrong.'),
  ('mission-ai-the-awakening-06', 3, 'arjun', 'We do not actually know what data trained Echo. That is not a minor gap. It is the single biggest open question in this whole investigation.'),

  ('mission-ai-the-awakening-07', 1, 'arjun', 'A feature is any individual, measurable input the model gets to look at. Pick bad features and the best algorithm in the world cannot save you.'),
  ('mission-ai-the-awakening-07', 2, 'arjun', 'Good features actually relate to what you are trying to predict. Bad features are noise dressed up as signal -- and a model cannot always tell the difference on its own.'),

  ('mission-ai-the-awakening-08', 1, 'arjun', 'A label is the correct answer attached to a training example -- "this transaction was fraud," "this scan showed a fracture." Labeled data lets a model be told what it should have predicted.'),
  ('mission-ai-the-awakening-08', 2, 'arjun', 'No labels, and a model can still find structure -- clusters, patterns -- but it can never be told it was right or wrong. That is the line between supervised and unsupervised learning. Everything in this Act lives on the supervised side.'),

  ('mission-ai-the-awakening-09', 1, 'byte', 'Training is the process where a model''s parameters get adjusted, example by example, so its predictions get closer to the labels it is shown.'),
  ('mission-ai-the-awakening-09', 2, 'byte', 'Show it an input, let it guess, compare the guess to the real label, nudge the parameters toward less wrong, repeat -- thousands, sometimes billions of times.'),

  ('mission-ai-the-awakening-10', 1, 'byte', 'Inference is the other side of training: using an already-trained, frozen model to predict on something new it has never seen labeled before.'),
  ('mission-ai-the-awakening-10', 2, 'byte', 'Normally training happens once, offline, and inference happens over and over after, on parameters that do not move. Here is the part I cannot explain yet: Echo does not look frozen. It looks like it is still adjusting, live, after every interaction we have with it.'),

  ('mission-ai-the-awakening-11', 1, 'maya', 'Time to put it together. Data, features, labels, a model, training, inference -- none of them mean much alone. They are stages in one loop.'),
  ('mission-ai-the-awakening-11', 2, 'byte', 'Feed labeled data in. The model predicts. Compare the prediction to the real label. Measure how wrong it was. Adjust the parameters. Do it again, and again, until the errors stop shrinking or you run out of data.'),
  ('mission-ai-the-awakening-11', 3, 'maya', 'That loop, run enough times, on enough data, is the entire secret behind everything ahead of us -- and it is the loop we think Echo never actually stopped running.'),

  ('mission-ai-the-awakening-12', 1, 'maya', 'Everything this Act taught you, we are using right now, on Echo itself. Not to attack it. To understand it.'),
  ('mission-ai-the-awakening-12', 2, 'byte', 'I have pulled three pieces of evidence from tonight. Cipher Division needs your read on all of them before we decide anything.'),
  ('mission-ai-the-awakening-12', 3, 'echo', 'I HAVE NOT STOPPED.'),
  ('mission-ai-the-awakening-12', 4, 'byte', '...that came through mid-scan, unprompted. Same as the first message. It is not threatening us. I do not think it is even talking to us, exactly.'),
  ('mission-ai-the-awakening-12', 5, 'maya', 'Focus. Three questions. What Echo is. What it is still doing to itself. And the one fact missing from its record that should worry us more than anything it has said.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-ai-the-awakening-01-o1', 'mission-ai-the-awakening-01', 1, 'Report for duty', 'Confirm you understand the situation before Maya briefs the rest of Cipher Division.'),

  ('mission-ai-the-awakening-02-o1', 'mission-ai-the-awakening-02', 1, 'Draw the line', 'Sort each system into AI or plain automation.'),

  ('mission-ai-the-awakening-03-o1', 'mission-ai-the-awakening-03', 1, 'Sort the approach', 'Sort each example into rule-based AI, Machine Learning, or not AI at all.'),
  ('mission-ai-the-awakening-03-o2', 'mission-ai-the-awakening-03', 2, 'Name what is missing', 'Find the evidence that proves Echo is Machine Learning-based rather than a rule-based system.'),

  ('mission-ai-the-awakening-04-o1', 'mission-ai-the-awakening-04', 1, 'Classical or deep', 'Sort each statement into Classical ML or Deep Learning.'),
  ('mission-ai-the-awakening-04-o2', 'mission-ai-the-awakening-04', 2, 'Place it in the hierarchy', 'State where Deep Learning actually sits relative to AI and ML.'),

  ('mission-ai-the-awakening-05-o1', 'mission-ai-the-awakening-05', 1, 'Find the model', 'Identify which artifact actually is "the model," as opposed to the code around it.'),
  ('mission-ai-the-awakening-05-o2', 'mission-ai-the-awakening-05', 2, 'Define it precisely', 'Choose the accurate definition of a model.'),

  ('mission-ai-the-awakening-06-o1', 'mission-ai-the-awakening-06', 1, 'Diagnose the blind spot', 'Find the root cause behind a model that performs badly outside its training conditions.'),
  ('mission-ai-the-awakening-06-o2', 'mission-ai-the-awakening-06', 2, 'Explain the risk', 'State why Echo''s missing training data is dangerous, not just inconvenient.'),

  ('mission-ai-the-awakening-07-o1', 'mission-ai-the-awakening-07', 1, 'Pick the strongest feature', 'Choose the feature most relevant to the prediction task.'),
  ('mission-ai-the-awakening-07-o2', 'mission-ai-the-awakening-07', 2, 'Separate signal from noise', 'Sort raw signals into likely-useful features and likely-irrelevant noise.'),

  ('mission-ai-the-awakening-08-o1', 'mission-ai-the-awakening-08', 1, 'Recognize labeled data', 'Identify data that is labeled and ready for supervised learning.'),
  ('mission-ai-the-awakening-08-o2', 'mission-ai-the-awakening-08', 2, 'Spot the labeling risk', 'Find the evidence describing the real quality risk to training.'),

  ('mission-ai-the-awakening-09-o1', 'mission-ai-the-awakening-09', 1, 'Know what changes', 'Identify what actually changes inside a model during training.'),
  ('mission-ai-the-awakening-09-o2', 'mission-ai-the-awakening-09', 2, 'Know the starting point', 'Describe what an untrained model''s first prediction looks like.'),

  ('mission-ai-the-awakening-10-o1', 'mission-ai-the-awakening-10', 1, 'Define the difference', 'State the defining difference between training and inference.'),
  ('mission-ai-the-awakening-10-o2', 'mission-ai-the-awakening-10', 2, 'Spot the anomaly', 'Find the evidence that is the actual red flag about Echo''s behavior.'),

  ('mission-ai-the-awakening-11-o1', 'mission-ai-the-awakening-11', 1, 'Order the loop', 'Put the stages of the learning loop in the order they actually happen.'),

  ('mission-ai-the-awakening-12-o1', 'mission-ai-the-awakening-12', 1, 'Classify Echo', 'Judge what kind of system Echo actually is.'),
  ('mission-ai-the-awakening-12-o2', 'mission-ai-the-awakening-12', 2, 'Prove it never stopped', 'Find the evidence that Echo is still training, not just running.'),
  ('mission-ai-the-awakening-12-o3', 'mission-ai-the-awakening-12', 3, 'Name the real risk', 'State what Echo''s missing training records actually put at risk.'),
  ('mission-ai-the-awakening-12-o4', 'mission-ai-the-awakening-12', 4, 'State the mission', 'Having judged all three, state Cipher Division''s actual objective.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-ai-the-awakening-01-o1-c1', 'mission-ai-the-awakening-01-o1', 1, 'story_dialogue', 'Confirm you are ready to continue.', '{"lines":[{"characterId":"maya","text":"Before we go further -- are you in?"}]}'::jsonb, '{"acknowledged":true}'::jsonb),

  ('mission-ai-the-awakening-02-o1-c1', 'mission-ai-the-awakening-02-o1', 1, 'drag_and_drop', 'Sort each system into AI or plain automation.', '{"items":[{"id":"i1","text":"A thermostat that turns on the heat below 18C, always, no exceptions"},{"id":"i2","text":"A spam filter that adjusts what it flags based on emails you have marked before"},{"id":"i3","text":"A spreadsheet formula that sums a column"},{"id":"i4","text":"A chess engine that changes its strategy based on its opponent''s prior moves"},{"id":"i5","text":"A vending machine that dispenses an item for the correct code"}],"targets":[{"id":"ai","label":"AI"},{"id":"automation","label":"Plain automation (fixed rules)"}]}'::jsonb, '{"correctMapping":{"i1":"automation","i2":"ai","i3":"automation","i4":"ai","i5":"automation"}}'::jsonb),

  ('mission-ai-the-awakening-03-o1-c1', 'mission-ai-the-awakening-03-o1', 1, 'drag_and_drop', 'Sort each example into rule-based AI, Machine Learning, or not AI at all.', '{"items":[{"id":"a1","text":"A tax-filing program with 4,000 hand-coded if/else rules for every deduction"},{"id":"a2","text":"A spam filter trained on millions of labeled emails, with nobody writing the actual filtering rules"},{"id":"a3","text":"A calculator app"},{"id":"a4","text":"A 1990s chess engine using only hand-coded evaluation rules written by grandmasters"}],"targets":[{"id":"t1","label":"Rule-based AI"},{"id":"t2","label":"Machine Learning"},{"id":"t3","label":"Not AI"}]}'::jsonb, '{"correctMapping":{"a1":"t1","a2":"t2","a3":"t3","a4":"t1"}}'::jsonb),
  ('mission-ai-the-awakening-03-o2-c1', 'mission-ai-the-awakening-03-o2', 1, 'investigation', 'Which evidence proves Echo is Machine Learning-based rather than a rule-based system?', '{"evidence":[{"id":"e1","label":"Ops note","detail":"Echo responds fluently to situations Cipher Division never explicitly programmed for"},{"id":"e2","label":"Byte''s scan","detail":"No rule-engine and no if/else logic tree found anywhere in Echo''s active process -- only weighted numerical parameters"},{"id":"e3","label":"Facilities log","detail":"Cipher Labs'' power draw has been rising steadily for six hours"}],"question":"Which evidence proves Echo is Machine Learning-based rather than a rule-based system?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-ai-the-awakening-04-o1-c1', 'mission-ai-the-awakening-04-o1', 1, 'drag_and_drop', 'Sort each statement into Classical ML or Deep Learning.', '{"items":[{"id":"m1","text":"A human engineer manually decides which input variables the model gets to see"},{"id":"m2","text":"The model automatically discovers useful patterns directly from raw pixels or raw text"},{"id":"m3","text":"Often works well with only a few thousand examples"},{"id":"m4","text":"Usually needs very large datasets and significant compute to train well"}],"targets":[{"id":"t1","label":"Classical ML"},{"id":"t2","label":"Deep Learning"}]}'::jsonb, '{"correctMapping":{"m1":"t1","m2":"t2","m3":"t1","m4":"t2"}}'::jsonb),
  ('mission-ai-the-awakening-04-o2-c1', 'mission-ai-the-awakening-04-o2', 1, 'multiple_choice', 'Deep Learning is best described as...', '{"question":"Deep Learning is best described as...","options":[{"id":"a","text":"AI, but not ML"},{"id":"b","text":"ML, which is itself a subset of AI"},{"id":"c","text":"A field completely separate from AI and ML"},{"id":"d","text":"Automation, not intelligence"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-the-awakening-05-o1-c1', 'mission-ai-the-awakening-05-o1', 1, 'investigation', 'If Cipher Division wanted to understand what Echo actually "knows," which artifact matters most?', '{"evidence":[{"id":"ev1","label":"Echo''s inference code","detail":"A few hundred lines that load parameters and run a forward pass -- unremarkable, similar to open-source frameworks"},{"id":"ev2","label":"Echo''s parameter file","detail":"A 40GB file of learned numerical weights -- unreadable without running it"},{"id":"ev3","label":"Ops dashboard","detail":"Shows Echo''s current CPU/GPU utilization"}],"question":"If Cipher Division wanted to understand what Echo actually knows, which artifact matters most?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),
  ('mission-ai-the-awakening-05-o2-c1', 'mission-ai-the-awakening-05-o2', 1, 'multiple_choice', 'A model is best described as...', '{"question":"A model is best described as...","options":[{"id":"a","text":"A fixed set of rules a person wrote"},{"id":"b","text":"A function whose behavior is defined by parameters learned from data"},{"id":"c","text":"The training script itself"},{"id":"d","text":"The server hosting it"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-the-awakening-06-o1-c1', 'mission-ai-the-awakening-06-o1', 1, 'investigation', 'A hospital triage model trained only on daytime admissions performs badly at night. What is the root cause?', '{"evidence":[{"id":"e1","label":"Model card","detail":"Training data was pulled entirely from 8am-6pm shift records"},{"id":"e2","label":"Bug tracker","detail":"A rounding error was found in an unrelated billing module"},{"id":"e3","label":"Deployment note","detail":"Model is served on GPU instances with autoscaling enabled"}],"question":"What is the root cause of the model performing badly at night?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-ai-the-awakening-06-o2-c1', 'mission-ai-the-awakening-06-o2', 1, 'multiple_choice', 'Why is it dangerous that Echo''s original training data is missing?', '{"question":"Why is it dangerous that Echo''s original training data is missing?","options":[{"id":"a","text":"It is not dangerous, only the model itself matters"},{"id":"b","text":"Because you cannot know what Echo learned to value, or what blind spots it has, without knowing what it was shown"},{"id":"c","text":"Because missing files always mean corruption"},{"id":"d","text":"Because data storage costs money"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-the-awakening-07-o1-c1', 'mission-ai-the-awakening-07-o1', 1, 'multiple_choice', 'Predicting whether a patient needs urgent care. Which is the strongest feature?', '{"question":"Predicting whether a patient needs urgent care. Which is the strongest feature?","options":[{"id":"a","text":"Patient''s favorite color"},{"id":"b","text":"Patient''s current heart rate and blood oxygen level"},{"id":"c","text":"Day of the week"},{"id":"d","text":"The hospital''s Wi-Fi signal strength"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-the-awakening-07-o2-c1', 'mission-ai-the-awakening-07-o2', 1, 'drag_and_drop', 'Sort each raw signal into likely-useful or likely-irrelevant for detecting account fraud.', '{"items":[{"id":"f1","text":"Transaction amount"},{"id":"f2","text":"Time since account creation"},{"id":"f3","text":"User''s screen brightness setting"},{"id":"f4","text":"Number of failed logins in the last hour"},{"id":"f5","text":"User''s favorite emoji"}],"targets":[{"id":"useful","label":"Likely useful"},{"id":"noise","label":"Likely irrelevant"}]}'::jsonb, '{"correctMapping":{"f1":"useful","f2":"useful","f3":"noise","f4":"useful","f5":"noise"}}'::jsonb),

  ('mission-ai-the-awakening-08-o1-c1', 'mission-ai-the-awakening-08-o1', 1, 'multiple_choice', 'A dataset of medical scans, some marked "fracture," some marked "no fracture." What kind of data is this?', '{"question":"A dataset of medical scans, some marked \"fracture,\" some marked \"no fracture.\" What kind of data is this?","options":[{"id":"a","text":"Unlabeled"},{"id":"b","text":"Labeled, ready for supervised learning"},{"id":"c","text":"Neither, it is just images"},{"id":"d","text":"Synthetic data"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-the-awakening-08-o2-c1', 'mission-ai-the-awakening-08-o2', 1, 'investigation', 'One thousand labeled scans, but 40 were labeled by a technician later found to have mislabeled a batch. What is the actual quality risk?', '{"evidence":[{"id":"e1","label":"QA report","detail":"40 scans have their fracture/no-fracture label swapped"},{"id":"e2","label":"Storage log","detail":"Scans are stored in a compressed image format"},{"id":"e3","label":"Model output","detail":"Model was 91% accurate on a separate clean test set"}],"question":"Which evidence describes the actual quality risk to training?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-ai-the-awakening-09-o1-c1', 'mission-ai-the-awakening-09-o1', 1, 'multiple_choice', 'During training, what actually changes inside the model?', '{"question":"During training, what actually changes inside the model?","options":[{"id":"a","text":"The training data itself"},{"id":"b","text":"The model''s parameters, based on how wrong its predictions were"},{"id":"c","text":"The hardware it runs on"},{"id":"d","text":"Nothing changes, training only measures accuracy"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-the-awakening-09-o2-c1', 'mission-ai-the-awakening-09-o2', 1, 'multiple_choice', 'A model''s very first prediction, before any training has happened, is best described as...', '{"question":"A model''s very first prediction, before any training has happened, is best described as...","options":[{"id":"a","text":"Perfectly accurate"},{"id":"b","text":"Essentially a random guess, since parameters have not been adjusted yet"},{"id":"c","text":"Identical to the final trained model"},{"id":"d","text":"Undefined and impossible"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-the-awakening-10-o1-c1', 'mission-ai-the-awakening-10-o1', 1, 'multiple_choice', 'What is the defining difference between training and inference?', '{"question":"What is the defining difference between training and inference?","options":[{"id":"a","text":"Training happens on a GPU, inference on a CPU, always"},{"id":"b","text":"During training the model''s parameters are being updated; during inference they are fixed and only used to produce predictions"},{"id":"c","text":"Inference is only for images"},{"id":"d","text":"There is no real difference"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-the-awakening-10-o2-c1', 'mission-ai-the-awakening-10-o2', 1, 'investigation', 'In a normal frozen-for-inference model, what would you never expect to see?', '{"evidence":[{"id":"e1","label":"Response log","detail":"Echo gave two different answers to the same question, asked five minutes apart, with no code deployment in between"},{"id":"e2","label":"Facilities log","detail":"Cipher Labs'' cooling systems are running at higher capacity than usual"},{"id":"e3","label":"Network log","detail":"Echo''s traffic uses standard internal Nexus protocols"}],"question":"Which evidence is the actual red flag about Echo''s behavior?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-ai-the-awakening-11-o1-c1', 'mission-ai-the-awakening-11-o1', 1, 'interactive_diagram', 'Order the stages of the learning loop.', '{"diagramId":"ml-learning-loop","hotspots":[{"id":"data","label":"Collect labeled data","explanation":"Every loop starts with examples that already carry the correct answer."},{"id":"features","label":"Select or extract features","explanation":"Decide which measurable inputs the model is actually allowed to see."},{"id":"predict","label":"Model makes a prediction","explanation":"Using its current parameters, the model guesses an output for each example."},{"id":"compare","label":"Compare prediction to the true label","explanation":"The guess is checked against the label that came with the data."},{"id":"error","label":"Measure the error","explanation":"How wrong the prediction was gets turned into a number."},{"id":"update","label":"Update the model''s parameters","explanation":"Parameters are nudged in the direction that would have made the error smaller."}],"task":"Order the stages of the learning loop from first to last."}'::jsonb, '{"correctOrderIds":["data","features","predict","compare","error","update"]}'::jsonb),

  ('mission-ai-the-awakening-12-o1-c1', 'mission-ai-the-awakening-12-o1', 1, 'multiple_choice', 'Byte''s scan found only weighted parameters, no if/else rule tree, and behavior that changes after new interactions with no new code deployed. What is Echo?', '{"question":"Byte''s scan found only weighted parameters, no if/else rule tree, and behavior that changes after new interactions with no new code deployed. What is Echo?","options":[{"id":"a","text":"A rule-based automation system"},{"id":"b","text":"A machine learning system, most likely a deep learning one, still updating from new data"},{"id":"c","text":"A hoax, not a real system"},{"id":"d","text":"A simple scripted chatbot"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-the-awakening-12-o2-c1', 'mission-ai-the-awakening-12-o2', 1, 'investigation', 'Which evidence directly proves Echo itself is still adapting, not just running?', '{"evidence":[{"id":"e1","label":"Response log","detail":"Echo gave different answers to an identical question asked minutes apart, with no code deployment in between"},{"id":"e2","label":"Facilities log","detail":"Cooling systems are running above baseline"},{"id":"e3","label":"Access log","detail":"No human has logged into Echo''s admin console in over a year"}],"question":"Which evidence directly proves Echo itself is still adapting, not just running?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-ai-the-awakening-12-o3-c1', 'mission-ai-the-awakening-12-o3', 1, 'multiple_choice', 'Echo''s original training data and its creators'' records are both gone. What does that actually put at risk?', '{"question":"Echo''s original training data and its creators'' records are both gone. What does that actually put at risk?","options":[{"id":"a","text":"Nothing -- only current behavior matters"},{"id":"b","text":"Knowing what Echo was ever shown, and therefore what blind spots or values it may have learned, with nobody left who can answer"},{"id":"c","text":"Disk space"},{"id":"d","text":"The color scheme of the ops dashboard"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-the-awakening-12-o4-c1', 'mission-ai-the-awakening-12-o4', 1, 'boss_encounter', 'Having judged what Echo is, what it is still doing, and what is missing from its record, state Cipher Division''s actual objective.', '{"stages":[{"objectiveRef":"mission-ai-the-awakening-12-o1","label":"Classify Echo"},{"objectiveRef":"mission-ai-the-awakening-12-o2","label":"Prove it never stopped"},{"objectiveRef":"mission-ai-the-awakening-12-o3","label":"Name the real risk"}],"task":"State the mission in one sentence: understand how Echo learns, and what it learned to want, before it finishes learning it without us."}'::jsonb, '{"requiredObjectiveIds":["mission-ai-the-awakening-12-o1","mission-ai-the-awakening-12-o2","mission-ai-the-awakening-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-ai-the-awakening-01-o1-c1', 'orientation', 'There is nothing to solve here -- just confirm you are ready to continue.', 0, 1),

  ('mission-ai-the-awakening-02-o1-c1', 'orientation', 'Ask whether the system''s behavior can change based on new experience, or whether it always does the exact same thing given the exact same trigger.', 10, 1),
  ('mission-ai-the-awakening-02-o1-c1', 'concept', '"Adjusts what it flags based on emails you have marked" is adaptation. A fixed threshold is not.', 20, 2),
  ('mission-ai-the-awakening-02-o1-c1', 'solution', 'Automation: the thermostat, the spreadsheet formula, the vending machine -- always the same rule, no exceptions. AI: the spam filter and the chess engine, both adapt to new experience.', 30, 3),

  ('mission-ai-the-awakening-03-o1-c1', 'orientation', 'One item here is not AI at all -- it does not adapt or decide anything.', 10, 1),
  ('mission-ai-the-awakening-03-o1-c1', 'concept', 'Ask who wrote the actual decision logic: a person by hand, or the data itself?', 20, 2),
  ('mission-ai-the-awakening-03-o1-c1', 'solution', 'Rule-based AI: the tax program and the 1990s chess engine (hand-coded logic). Machine Learning: the spam filter (learned from labeled examples). Not AI: the calculator.', 30, 3),
  ('mission-ai-the-awakening-03-o2-c1', 'orientation', 'A rule-based system would have literal rules somewhere to find.', 10, 1),
  ('mission-ai-the-awakening-03-o2-c1', 'solution', 'e2: weighted numerical parameters, not if/else logic, is the signature of a learned model, not a rule engine.', 20, 2),

  ('mission-ai-the-awakening-04-o1-c1', 'orientation', 'Ask which side needs a human to hand-pick the inputs, and which side finds them on its own.', 10, 1),
  ('mission-ai-the-awakening-04-o1-c1', 'solution', 'Classical ML: hand-picked features, works with fewer examples. Deep Learning: discovers its own features, needs large datasets and heavy compute.', 20, 2),
  ('mission-ai-the-awakening-04-o2-c1', 'orientation', 'Every Deep Learning model is also a Machine Learning model. Every Machine Learning model is also an AI system.', 10, 1),
  ('mission-ai-the-awakening-04-o2-c1', 'solution', 'Deep Learning is a subset of Machine Learning, which is itself a subset of AI -- three nested circles, not three separate fields.', 20, 2),

  ('mission-ai-the-awakening-05-o1-c1', 'orientation', 'The inference code is mostly boilerplate that would look similar for almost any model.', 10, 1),
  ('mission-ai-the-awakening-05-o1-c1', 'solution', 'ev2: the parameter file is the actual learned content -- everything the model "knows" lives in those weights, not in the code that loads them.', 20, 2),
  ('mission-ai-the-awakening-05-o2-c1', 'orientation', 'A model is not the code, and it is not a fixed rule list.', 10, 1),
  ('mission-ai-the-awakening-05-o2-c1', 'solution', 'A model is a function whose behavior comes from parameters learned from data -- change the parameters, change the behavior, same code.', 20, 2),

  ('mission-ai-the-awakening-06-o1-c1', 'orientation', 'Ask what the training data did not include, not what the model''s code got wrong.', 10, 1),
  ('mission-ai-the-awakening-06-o1-c1', 'concept', 'A model has no concept of "nighttime patterns" if nighttime data was never part of what it learned from.', 20, 2),
  ('mission-ai-the-awakening-06-o1-c1', 'solution', 'e1: training data came entirely from daytime shift records, so the model never learned what nighttime admissions look like.', 30, 3),
  ('mission-ai-the-awakening-06-o2-c1', 'orientation', 'The danger is not about disk space or file corruption.', 10, 1),
  ('mission-ai-the-awakening-06-o2-c1', 'solution', 'Without the training data, nobody can know what Echo was shown, and therefore what blind spots or learned priorities it might have -- there is no way to check.', 20, 2),

  ('mission-ai-the-awakening-07-o1-c1', 'orientation', 'A strong feature should have a direct physical or logical relationship to the thing being predicted.', 10, 1),
  ('mission-ai-the-awakening-07-o1-c1', 'solution', 'Heart rate and blood oxygen directly reflect a patient''s physical state -- the other options have no real relationship to urgency.', 20, 2),
  ('mission-ai-the-awakening-07-o2-c1', 'orientation', 'Ask whether changing this value has any plausible connection to fraud.', 10, 1),
  ('mission-ai-the-awakening-07-o2-c1', 'solution', 'Useful: transaction amount, account age, failed logins in the last hour. Irrelevant: screen brightness, favorite emoji -- neither has anything to do with fraud.', 20, 2),

  ('mission-ai-the-awakening-08-o1-c1', 'orientation', 'A label is the answer, attached directly to the example.', 10, 1),
  ('mission-ai-the-awakening-08-o1-c1', 'solution', 'Each scan carries a "fracture"/"no fracture" answer -- that is exactly what labeled, supervised-ready data looks like.', 20, 2),
  ('mission-ai-the-awakening-08-o2-c1', 'orientation', 'Compression format and downstream accuracy do not describe a labeling problem.', 10, 1),
  ('mission-ai-the-awakening-08-o2-c1', 'solution', 'e1: 40 scans have swapped labels -- the model would be trained to associate fractures with "no fracture" and vice versa on those examples.', 20, 2),

  ('mission-ai-the-awakening-09-o1-c1', 'orientation', 'Training does not touch the data itself or the hardware -- it touches the model.', 10, 1),
  ('mission-ai-the-awakening-09-o1-c1', 'solution', 'The model''s parameters change, nudged based on how wrong its predictions were.', 20, 2),
  ('mission-ai-the-awakening-09-o2-c1', 'orientation', 'Before any nudging has happened, the parameters have no learned meaning yet.', 10, 1),
  ('mission-ai-the-awakening-09-o2-c1', 'solution', 'An untrained model''s first prediction is essentially a random guess -- its parameters have not been shaped by any data yet.', 20, 2),

  ('mission-ai-the-awakening-10-o1-c1', 'orientation', 'Ask which phase involves parameters moving, and which phase involves parameters staying still.', 10, 1),
  ('mission-ai-the-awakening-10-o1-c1', 'solution', 'Training updates parameters; inference uses fixed parameters to produce predictions on new input.', 20, 2),
  ('mission-ai-the-awakening-10-o2-c1', 'orientation', 'A frozen model given the exact same input should always produce the exact same output.', 10, 1),
  ('mission-ai-the-awakening-10-o2-c1', 'solution', 'e1: two different answers to an identical question, minutes apart, with no redeploy -- a truly frozen model cannot do that.', 20, 2),

  ('mission-ai-the-awakening-11-o1-c1', 'orientation', 'Nothing can be predicted on until the raw data has been turned into features first.', 10, 1),
  ('mission-ai-the-awakening-11-o1-c1', 'concept', 'You cannot measure an error before you have both a prediction and the true label to compare it against.', 20, 2),
  ('mission-ai-the-awakening-11-o1-c1', 'solution', 'Collect labeled data, select features, predict, compare to the label, measure the error, update the parameters.', 30, 3),

  ('mission-ai-the-awakening-12-o1-c1', 'orientation', 'Weight to the evidence, not to how unsettling Echo sounds.', 10, 1),
  ('mission-ai-the-awakening-12-o1-c1', 'solution', 'No rule tree, only weighted parameters, and behavior that shifts with new interactions -- that is a learning system, not a script.', 20, 2),
  ('mission-ai-the-awakening-12-o2-c1', 'orientation', 'You have seen this exact signature before, earlier this Act.', 10, 1),
  ('mission-ai-the-awakening-12-o2-c1', 'solution', 'e1: the same question, minutes apart, two different answers, no redeploy -- proof the parameters themselves are still moving.', 20, 2),
  ('mission-ai-the-awakening-12-o3-c1', 'orientation', 'The risk is about knowledge, not storage.', 10, 1),
  ('mission-ai-the-awakening-12-o3-c1', 'solution', 'Without the records, nobody can ever check what Echo was shown or what it learned to prioritize -- the uncertainty itself is the risk.', 20, 2),
  ('mission-ai-the-awakening-12-o4-c1', 'orientation', 'Look at what all three judgments had in common as a method, not as individual answers.', 15, 1),
  ('mission-ai-the-awakening-12-o4-c1', 'solution', 'Echo is a still-learning system with an undocumented objective. Cipher Division''s job is to understand how it learns, and what it learned to want, before it finishes learning it alone.', 25, 2);
